<?php
declare(strict_types=1);
function pbRouteHttp(string $url): array {$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>25,CURLOPT_HTTPHEADER=>['User-Agent: SV-Netzwerk-Portal/1.0 (info@sv-netzwerk.eu)','Accept: application/json']]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=is_string($body)?json_decode($body,true):null;if($status!==200||!is_array($data))throw new RuntimeException('Routenservice derzeit nicht erreichbar. Strecke und Fahrzeit können manuell eingetragen werden.');return$data;}
function pbGeocode(array $a): array {foreach(['street','postcode','city']as$k)if(trim((string)($a[$k]??''))==='')throw new RuntimeException('Bitte Straße, PLZ und Ort vollständig eingeben.');$q=http_build_query(['street'=>$a['street'],'postalcode'=>$a['postcode'],'city'=>$a['city'],'country'=>'Germany','countrycodes'=>'de','format'=>'jsonv2','addressdetails'=>1,'limit'=>2]);$rows=pbRouteHttp('https://nominatim.openstreetmap.org/search?'.$q);if(count($rows)!==1)throw new RuntimeException('Adresse nicht eindeutig gefunden. Bitte Anschrift prüfen oder Strecke und Fahrzeit manuell eintragen.');$r=$rows[0];if(($r['address']['postcode']??'')!==$a['postcode']||!isset($r['address']['house_number']))throw new RuntimeException('Die Hausadresse konnte nicht genau zugeordnet werden. Bitte Anschrift prüfen.');return$r;}
function pbRoute(array $data): array {$d=pbClean($data,'christian');$from=pbGeocode(pbOrigin($d));usleep(1100000);$to=pbGeocode(pbSite($d));$url='https://router.project-osrm.org/route/v1/driving/'.rawurlencode($from['lon']).','.rawurlencode($from['lat']).';'.rawurlencode($to['lon']).','.rawurlencode($to['lat']).'?overview=false';$r=pbRouteHttp($url);if(($r['code']??'')!=='Ok'||!isset($r['routes'][0]['distance'],$r['routes'][0]['duration']))throw new RuntimeException('Keine Fahrstrecke gefunden. Bitte Werte manuell eingeben.');return['oneway_km'=>round($r['routes'][0]['distance']/1000,1),'oneway_minutes'=>(int)ceil($r['routes'][0]['duration']/60),'route_source'=>'OpenStreetMap / OSRM · '.gmdate('Y-m-d H:i').' UTC','from'=>$from['display_name'],'to'=>$to['display_name']];}
